import { Cart, Category, ErrorEvent, Identity, PartyIdentification } from '../events';
/**
Description: Checkout step in which the shopper enters payment information. No payment details are captured in the event.
*/
export type CheckoutPayment = {
    events: Array<Cart | Identity | PartyIdentification | ErrorEvent>;
}

export class CheckoutPaymentBuilder {

    private checkoutPayment: CheckoutPayment = {
        events: []
    }

    private cart!: Cart;
    private errorEvent!: ErrorEvent;
    private identity!: Identity;
    private partyIdentification!: PartyIdentification;

    public withCart(cart: Cart) : CheckoutPaymentBuilder {
        this.cart = cart;
        return this;
    }
    public withErrorEvent(errorEvent: ErrorEvent) : CheckoutPaymentBuilder {
        this.errorEvent = errorEvent;
        return this;
    }
    public withIdentity(identity: Identity) : CheckoutPaymentBuilder {
        this.identity = identity;
        return this;
    }
    public withPartyIdentification(partyIdentification: PartyIdentification) : CheckoutPaymentBuilder {
        this.partyIdentification = partyIdentification;
        return this;
    }

    public build() : CheckoutPayment {
        if(this.cart) {
            this.checkoutPayment.events.push(this.cart);
        }
        if(this.errorEvent) {
            this.checkoutPayment.events.push(this.errorEvent);
        }
        if(this.identity) {
            this.checkoutPayment.events.push(this.identity);
        }
        if(this.partyIdentification) {
            this.checkoutPayment.events.push(this.partyIdentification);
        }

        return this.checkoutPayment;
    }
}
